{
  "packet_id": "H6-T05-2",
  "claims": [
    {
      "claim_id": "C001",
      "fields": ["state"],
      "component": {
        "component_id": "C001",
        "value": "Unresolved metadata questions may leave traces in folder records or handoff histories that scanning totals do not expose.",
        "scope": "Possible traces, without asserting their presence or establishing a cause of the backlog.",
        "provenance": {
          "refs": [
            {"source_id": "P001", "role": "SUPPORT"},
            {"source_id": "P002", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "The bundle identifies this possible source of hidden traces and limits their causal interpretation."
        }
      }
    },
    {
      "claim_id": "C002",
      "fields": ["state"],
      "component": {
        "component_id": "C002",
        "value": "Rights requests may leave traces in folder records or handoff histories that scanning totals do not expose.",
        "scope": "Possible traces, without asserting their presence or establishing a cause of the backlog.",
        "provenance": {
          "refs": [
            {"source_id": "P001", "role": "SUPPORT"},
            {"source_id": "P002", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "The bundle identifies rights requests as a possible source of hidden traces and supplies the causal limitation."
        }
      }
    },
    {
      "claim_id": "C003",
      "fields": ["state"],
      "component": {
        "component_id": "C003",
        "value": "Failed transfers may leave traces in folder records or handoff histories that scanning totals do not expose.",
        "scope": "Possible traces, without asserting their presence or establishing a cause of the backlog.",
        "provenance": {
          "refs": [
            {"source_id": "P001", "role": "SUPPORT"},
            {"source_id": "P002", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "The bundle identifies failed transfers as a possible source of hidden traces and supplies the causal limitation."
        }
      }
    },
    {
      "claim_id": "C004",
      "fields": ["state"],
      "component": {
        "component_id": "C004",
        "value": "The traces are proposed as potentially diagnostic residues.",
        "scope": "Diagnostic potential only; no successful diagnosis is reported.",
        "provenance": {
          "refs": [
            {"source_id": "P002", "role": "SUPPORT"},
            {"source_id": "P001", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P002 supplies the proposed diagnostic interpretation; P001 identifies the traces."
        }
      }
    },
    {
      "claim_id": "C005",
      "fields": ["state", "inference"],
      "component": {
        "component_id": "C005",
        "value": "The traces, including supported flags derived from them, do not establish why the backlog or delay arose.",
        "scope": "A limit on causal explanation, including when a flag supports a local finding about work or records.",
        "provenance": {
          "refs": [
            {"source_id": "P002", "role": "SUPPORT"},
            {"source_id": "P017", "role": "SUPPORT"},
            {"source_id": "P001", "role": "CONTEXT"},
            {"source_id": "P016", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P002 and P017 state the causal limitation; the context spans identify the traces and flag inference."
        }
      }
    },
    {
      "claim_id": "C006",
      "fields": ["state"],
      "component": {
        "component_id": "C006",
        "value": "Folders are assumed to be linkable by identifier across processing stages.",
        "scope": "An assumption requiring verification, not an established property of the records.",
        "provenance": {
          "refs": [{"source_id": "P003", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P003 explicitly presents cross-stage identifier linkage as an assumption."
        }
      }
    },
    {
      "claim_id": "C007",
      "fields": ["state"],
      "component": {
        "component_id": "C007",
        "value": "Cross-stage identifier linkage must be verified before counts are interpreted.",
        "scope": "A prerequisite for interpreting the project's counts.",
        "provenance": {
          "refs": [{"source_id": "P003", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P003 directly places verification before count interpretation."
        }
      }
    },
    {
      "claim_id": "C008",
      "fields": ["state", "inference"],
      "component": {
        "component_id": "C008",
        "value": "Exhibition readiness requires the museum's agreed metadata and rights evidence, and only folders meeting those criteria may count toward exhibition scope.",
        "scope": "The mapping's readiness and counting rule; no particular folder is declared ready.",
        "provenance": {
          "refs": [
            {"source_id": "P004", "role": "SUPPORT"},
            {"source_id": "P024", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P004 defines the evidence requirement and P024 applies the same readiness criterion to counting."
        }
      }
    },
    {
      "claim_id": "C009",
      "fields": ["state"],
      "component": {
        "component_id": "C009",
        "value": "The museum's required metadata and rights evidence must be specified before the readiness standard is applied.",
        "scope": "A prerequisite; the mapping does not supply the substantive evidence standard.",
        "provenance": {
          "refs": [{"source_id": "P004", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P004 explicitly requires prior specification of the agreed evidence."
        }
      }
    },
    {
      "claim_id": "C010",
      "fields": ["operation"],
      "component": {
        "component_id": "C010",
        "value": "The proposed diagnostic operation reconciles each sampled folder's recorded stage against dated review decisions, outstanding questions, rights evidence, and handoff acknowledgments.",
        "scope": "A proposed evidence-comparison method, without a claim that it has already succeeded.",
        "provenance": {
          "refs": [{"source_id": "P005", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P005 supplies the proposed probe and the records it compares."
        }
      }
    },
    {
      "claim_id": "C011",
      "fields": ["operation"],
      "component": {
        "component_id": "C011",
        "value": "Following reviewer reconciliation against the records, unresolved traces are to trigger a localized flag identifying the folder, stage, missing evidence, and next action.",
        "scope": "A proposed conditional flag-generation rule for traces remaining unresolved.",
        "provenance": {
          "refs": [
            {"source_id": "P006", "role": "SUPPORT"},
            {"source_id": "P005", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P006 states the reviewer step, trigger, and flag contents; P005 identifies the comparison records."
        }
      }
    },
    {
      "claim_id": "C012",
      "fields": ["operation"],
      "component": {
        "component_id": "C012",
        "value": "The proposed probability-sampling budget is 20 randomly selected histories distributed across recorded stages and available size, completeness, and queue-age groups.",
        "scope": "A proposed budget and sampling design; allocation among groups is unspecified, and adequacy is not asserted.",
        "provenance": {
          "refs": [{"source_id": "P007", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P007 supplies the number, random selection, grouping dimensions, and availability qualifier."
        }
      }
    },
    {
      "claim_id": "C013",
      "fields": ["operation"],
      "component": {
        "component_id": "C013",
        "value": "A separate examination of suspicious histories is limited to at most five additional histories.",
        "scope": "Supplementary investigation kept separate from the probability sample and excluded from prevalence estimation.",
        "provenance": {
          "refs": [{"source_id": "P008", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P008 states the supplementary examination's cap, separation, and estimation restriction."
        }
      }
    },
    {
      "claim_id": "C014",
      "fields": ["operation", "inference"],
      "component": {
        "component_id": "C014",
        "value": "Prevalence estimates must use only the probability sample, excluding the additional suspicious histories.",
        "scope": "Restriction on prevalence estimation, not on examining suspicious cases for other purposes.",
        "provenance": {
          "refs": [
            {"source_id": "P008", "role": "SUPPORT"},
            {"source_id": "P020", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "Both spans state the same estimation boundary from complementary directions."
        }
      }
    },
    {
      "claim_id": "C015",
      "fields": ["inference"],
      "component": {
        "component_id": "C015",
        "value": "Prevalence estimates from the probability sample require appropriate weighting.",
        "scope": "The mapping does not specify a weighting formula.",
        "provenance": {
          "refs": [{"source_id": "P020", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P020 explicitly requires weighting for probability-sample prevalence estimates."
        }
      }
    },
    {
      "claim_id": "C016",
      "fields": ["inference"],
      "component": {
        "component_id": "C016",
        "value": "Prevalence estimates from the probability sample must include appropriate uncertainty.",
        "scope": "The mapping does not specify an uncertainty method or confidence level.",
        "provenance": {
          "refs": [{"source_id": "P020", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P020 explicitly attaches uncertainty to the prevalence estimates."
        }
      }
    },
    {
      "claim_id": "C017",
      "fields": ["operation"],
      "component": {
        "component_id": "C017",
        "value": "Examination of a history must stop when its evidence is reconciled or its predefined time allowance expires.",
        "scope": "A per-history stopping bound; the allowance's duration is unspecified.",
        "provenance": {
          "refs": [{"source_id": "P011", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P011 supplies both alternative stopping conditions."
        }
      }
    },
    {
      "claim_id": "C018",
      "fields": ["operation"],
      "component": {
        "component_id": "C018",
        "value": "Cases whose examination expires or whose histories are inaccessible must be classified as inconclusive.",
        "scope": "An interpretation rule for these cases, without treating them as resolved or ready.",
        "provenance": {
          "refs": [{"source_id": "P011", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P011 explicitly assigns the inconclusive classification to expired and inaccessible cases."
        }
      }
    },
    {
      "claim_id": "C019",
      "fields": ["operation"],
      "component": {
        "component_id": "C019",
        "value": "If identifiers or stage definitions cannot be reconciled, that measurement problem must be repaired before completion is projected.",
        "scope": "A conditional prerequisite for projection, not an assertion that reconciliation has failed.",
        "provenance": {
          "refs": [{"source_id": "P012", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P012 directly states the failure condition and required ordering."
        }
      }
    },
    {
      "claim_id": "C020",
      "fields": ["signal"],
      "component": {
        "component_id": "C020",
        "value": "A recorded review completion lacking the required decision is a proposed flag that reconciliation might reveal beyond routine totals.",
        "scope": "A proposed signal type, not an observed finding.",
        "provenance": {
          "refs": [
            {"source_id": "P013", "role": "SUPPORT"},
            {"source_id": "P014", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P013 names this candidate signal and P014 supplies its unobserved, proposed status."
        }
      }
    },
    {
      "claim_id": "C021",
      "fields": ["signal"],
      "component": {
        "component_id": "C021",
        "value": "An unanswered rights request is a proposed flag that reconciliation might reveal beyond routine totals.",
        "scope": "A proposed signal type, not an observed finding.",
        "provenance": {
          "refs": [
            {"source_id": "P013", "role": "SUPPORT"},
            {"source_id": "P014", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P013 names this candidate signal and P014 supplies its unobserved, proposed status."
        }
      }
    },
    {
      "claim_id": "C022",
      "fields": ["signal"],
      "component": {
        "component_id": "C022",
        "value": "A transfer lacking acknowledgment is a proposed flag that reconciliation might reveal beyond routine totals.",
        "scope": "A proposed signal type, not an observed finding.",
        "provenance": {
          "refs": [
            {"source_id": "P013", "role": "SUPPORT"},
            {"source_id": "P014", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P013 names this candidate signal and P014 supplies its unobserved, proposed status."
        }
      }
    },
    {
      "claim_id": "C023",
      "fields": ["signal"],
      "component": {
        "component_id": "C023",
        "value": "Confirmed unresolved work, explained discrepancies, and inconclusive cases must remain distinct flag dispositions.",
        "scope": "A proposed interpretive distinction, without reporting any cases in those categories.",
        "provenance": {
          "refs": [{"source_id": "P015", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P015 explicitly requires the three-way distinction."
        }
      }
    },
    {
      "claim_id": "C024",
      "fields": ["signal"],
      "component": {
        "component_id": "C024",
        "value": "The proposed completion-rate observation uses staffed hours as its denominator and compares folders within comparable groups.",
        "scope": "A prescribed measurement basis; no measured rate or group-comparability test is supplied.",
        "provenance": {
          "refs": [{"source_id": "P015", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P015 specifies completion per staffed hour within comparable folder groups."
        }
      }
    },
    {
      "claim_id": "C025",
      "fields": ["operation", "signal"],
      "component": {
        "component_id": "C025",
        "value": "A resolution caused by the probe is an intervention and must be recorded separately from evidence of the pre-probe state.",
        "scope": "Distinguishes probe-generated changes from prior-state evidence.",
        "provenance": {
          "refs": [
            {"source_id": "P015", "role": "SUPPORT"},
            {"source_id": "P010", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P015 states the intervention distinction and separate recording; P010 also requires separate logging of probe-generated changes."
        }
      }
    },
    {
      "claim_id": "C026",
      "fields": ["inference"],
      "component": {
        "component_id": "C026",
        "value": "If a flag is supported, it supports a local conclusion that the specified folder contains evidence of unresolved work or inconsistent recording.",
        "scope": "Supported flags only. The disjunction remains unresolved: the claim does not establish which alternative applies. A formal support threshold is unspecified.",
        "provenance": {
          "refs": [{"source_id": "P016", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P016 supplies the support condition, evidential conclusion, alternatives, and location restriction."
        }
      }
    },
    {
      "claim_id": "C027",
      "fields": ["inference"],
      "component": {
        "component_id": "C027",
        "value": "The next two weeks of assignments should direct suitably trained volunteers to a demonstrated metadata or rights constraint, informed by recurring supported flags, queue growth, and measured effort.",
        "scope": "A proposed evidence-based assignment rule, subject to actual volunteer availability and required rights authority.",
        "provenance": {
          "refs": [
            {"source_id": "P018", "role": "SUPPORT"},
            {"source_id": "P019", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P018 supplies the evidence, horizon, and allocation rule; P019 supplies the resource and authority bounds."
