    {
      "claim_id": "C028",
      "fields": ["inference"],
      "component": {
        "component_id": "C028",
        "value": "The next two weeks of assignments should give external dependencies identifiable owners as part of planning informed by recurring supported flags, queue growth, and measured effort.",
        "scope": "A proposed assignment response, subject to actual volunteer availability and required rights authority; ownership is not asserted to resolve the dependency.",
        "provenance": {
          "refs": [
            {"source_id": "P018", "role": "SUPPORT"},
            {"source_id": "P019", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P018 proposes dependency ownership within the evidence-informed plan, and P019 bounds assignments."
        }
      }
    },
    {
      "claim_id": "C029",
      "fields": ["inference"],
      "component": {
        "component_id": "C029",
        "value": "Additional scanning should be limited where it would only add to waiting inventory.",
        "scope": "A conditional response within the proposed next-two-week plan; it does not call for an unconditional scanning limit.",
        "provenance": {
          "refs": [{"source_id": "P018", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P018 explicitly makes the scanning restriction conditional on merely increasing waiting inventory."
