      "fields": ["inference", "limit"],
      "component": {
        "component_id": "C032",
        "value": "Ten-week readiness should be estimated as a range using stage-specific throughput, folder mix, remaining work, and scheduled hours.",
        "scope": "A proposed estimation method conditional on staffing, folder mix, rework, and external rights responses; inadequate inputs may require wider ranges or withholding a forecast.",
        "provenance": {
          "refs": [
            {"source_id": "P020", "role": "SUPPORT"},
            {"source_id": "P028", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P020 supplies the output form, horizon, and inputs; P028 supplies material projection conditions and the inadequate-input limitation."
        }
      }
    },
    {
      "claim_id": "C033",
      "fields": ["inference", "limit"],
      "component": {
        "component_id": "C033",
        "value": "If even the optimistic supported readiness estimate is below the promised scope, a reduction or change in that scope should be proposed promptly.",
        "scope": "A conditional decision rule, not a finding of shortfall. The estimate remains conditional on projection inputs; the statistical meaning of optimistic supported is unspecified.",
