          "refs": [
            {"source_id": "P022", "role": "SUPPORT"},
            {"source_id": "P028", "role": "SUPPORT"},
            {"source_id": "P020", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P022 states the condition and response; P028 limits the projection and P020 identifies the readiness estimate."
        }
      }
    },
    {
      "claim_id": "C034",
      "fields": ["inference", "limit"],
      "component": {
        "component_id": "C034",
        "value": "If the readiness-estimate range crosses the promised scope, a contingent reduced scope should be identified.",
