        "provenance": {
          "refs": [
            {"source_id": "P023", "role": "SUPPORT"},
            {"source_id": "P028", "role": "SUPPORT"},
            {"source_id": "P020", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P023 supplies the crossing condition and contingency response; the other spans identify and qualify the estimate."
        }
      }
    },
    {
      "claim_id": "C035",
      "fields": ["inference", "limit"],
      "component": {
        "component_id": "C035",
        "value": "If the readiness-estimate range crosses the promised scope, targeted evidence should be gathered before the week-two decision.",
